import { ParameterSpecRecord } from "#base/scripts/voronoi-types.js";

import { RegionCell, VoronoiUtils } from "../voronoi-utils.js";
import { Rule, ScoringContext } from "../voronoi_rules/rules-base.js";

const ruleSchema = {
	scaleFactor: {
		label: "Mid Point",
		description:
			"The cell area that represents a score of 0.5. Any cell smaller will score between 0 and 0.5, and any cell larger will score between 0.5 and 1.0",
		default: 1,
		min: 0,
		max: 5,
		step: 0.1,
	},
	min: {
		label: "Min",
		description: "Values at or lower than this are scored 0.",
		default: 0,
		min: 0,
		max: 10,
		step: 0.1,
	},
	max: {
		label: "Max",
		description: "Values at or higher than this are scored 1.",
		default: 10,
		min: 0,
		max: 10,
		step: 0.1,
	},
	invert: {
		label: "Invert",
		description: "Invert the calculation to score smaller cells higher.",
		default: 0,
		min: 0,
		max: 1,
		step: 1,
	},
} as const satisfies ParameterSpecRecord;

export class RuleCellArea extends Rule {
	override parameterSpecs = ruleSchema;
	override configValues = Rule.createDefaultsFromSpecs(ruleSchema);
	override name = RuleCellArea.getName();
	override description =
		"This is a simple rule that scores larger cells higher than smaller cells. This is primary used to add some random variation to the score.";

	private m_diff = 1;
	private m_invBias = 1;

	static getName(): string {
		return "Cell Area";
	}

	static getSchema() {
		return ruleSchema;
	}

	prepare(): void {
		this.m_diff = this.configValues.max - this.configValues.min;
		const mid = VoronoiUtils.clamp(this.configValues.scaleFactor, this.configValues.min, this.configValues.max);
		this.m_invBias = 1 / (1 - (mid - this.configValues.min) / this.m_diff);
	}

	score(cell: RegionCell, _ctx: ScoringContext): number {
		const cellArea = VoronoiUtils.calculateCellArea(cell.cell);
		const score = VoronoiUtils.clamp((cellArea - this.configValues.min) / this.m_diff, 0, 1);
		const scoreBiased = VoronoiUtils.schlickInvBias(score, this.m_invBias);
		return this.configValues.invert > 0 ? 1.0 - scoreBiased : scoreBiased;
	}
}
